def h(i,title,signal,sids,mechanism,counter,test,anc,outcome,revisit,programmes_):
 hyp.append({'hypothesis_id':'H-UFA-'+i,'title':title,'signal':signal,'source_ids':sids,'mechanism':mechanism,'counterfactual':counter,'distinguishing_test':test,'ancestorIDs':anc,'stage_A_outcome':outcome,'economic_acceptance':'NOT_EVALUATED_IN_COMMON_P05_P06','condition_for_reconsideration':revisit,'programme_ids':programmes_,'status':'CONDITIONAL' if not outcome.startswith('REJECTED') else 'REJECTED_NARROW_CLAIM','period':PERIOD,'unit':'Конечные поездки, сегменты, физические рейсы, RUB; численный итог UNKNOWN.','coverage':'Локальная гипотеза, не вердикт всей системе Уфы.','assumption_ids':['UFA-A12','UFA-A13','UFA-A14','UFA-A16','UFA-A24']})
h('01','Малая прямая программа TOF/KEJ/OMS','В индексах TOF/KEJ не найдены; в истории KEJ был один субсидируемый рейс в неделю. Существует собственная длинная поездка через SVX.',['UFA-E10','UFA-E13','UFA-E16','PIN-AUTHOR'],'Прямой рейс сокращает время; редкие поездки с несколькими ночами могут поддержать меньшую частоту.','Тот же новый борт на лучах SVX и улучшенный feeder UFA; плюс отсутствие местного расширения.','P01 против P02 и P00: единые OD, свои продажи, пригодные возвраты; никакого независимого захвата одного OD двумя программами.',['E01','C01','UFA-F03','UFA-S01'],'CONDITIONAL: конкретные частоты и ротация построены; спрос и экономика не установлены.','Недостаток прямого спроса при всех обоснованных частотах либо более эффективная альтернатива борта; пересмотр при подтверждённых блоках или спросе.',['UFA-P01-RADIAL','UFA-P02-SVX'])
h('02','Защищённый банк запад–восток','Есть местная технология трансфера и рынки MRV/GOJ; старые TOF/KEJ сильно зависели от модельного трансфера.',['UFA-E07','UFA-E13','UFA-S09','UFA-S14','PIN-AUTHOR'],'Синхронизация двух самолётов создаёт совместные поездки четырёх пар между лучами.','Те же рейсы без банка; два борта в существующей SVX; будущий KEEP.','P04 bank против unbanked и P05 direct2: общий OD, MCT 60/90/120, багаж/ответственность, ночёвки, восстановление и цена единой поездки.',['E01','C01','EC_H01','EC_H04','T16_HUB_UFA','UFA-F05'],'CONDITIONAL: механически проверен двухбортный пример; защищённая продажа и общая экономика UNKNOWN.','Если защищённый продукт недоступен или стоимость синхронизации превышает его рассчитанную ценность, уменьшить банк либо перейти к прямым продуктам; это не отказ всем хабам Уфы.',['UFA-P04-BANK-EW','UFA-P05-DIRECT2'])
h('03','Цепочка из SVX без постоянной базы в Уфе','Есть собственный UFA–SVX и препятствие доступу неместных бортов в ангары.',['UFA-E06','UFA-S08'],'Использовать Уфу как промежуточную рабочую станцию; ночёвки на восточных концах заменяют длинный однодневный pendulum.','Один борт с базой UFA либо прямые рейсы SVX.','Сопоставить одинаковую частоту каждого луча: все перегонные/продаваемые плечи, прежние назначения feeder, ночёвки, crew/ТО. Однодневный шаблон TOF/KEJ не проходит выбранные 8 часов.',['C10','KIR_Н4','KIR_Н9','KIR_G4'],'CONDITIONAL: двухдневная геометрия построена; замена feeder и стоимость чужих ночёвок не приняты.','Согласованное ангарное/линейное ТО в UFA или подтверждённые меньшие блоки могут изменить выбор; отсутствие чужих ночёвок требует нового расписания.',['UFA-P03-OUTSTATION','UFA-P01-RADIAL'])
h('04','Дополнительная дата UFA–NUX','RW уже присутствует, конкуренты имеют частые северные продукты; вахтовый механизм возможен, но договор не получен.',['UFA-S16','UFA-S41','PIN-P02'],'Новая дата может лучше совпасть со сменой или семейной поездкой, не требуя открытия полностью нового рынка.','Тот же борт и омский оборот из P01; перенос старых NUX между днями учитывается.','P06-NORTH против P01: конечные новые поездки, собственный переток, release блока, багаж, возможность конкурентного изменения времени.',['C11','EC_H08','KIR_Н4','UFA-F02'],'CONDITIONAL: ротация и изменение ассортимента заданы; корпоративный спрос UNKNOWN.','Реальный блок/расписательная ниша усиливают гипотезу; перенос только старых продаж без нового эффекта ослабляет.',['UFA-P06-NORTH'])
h('05','Партнёрский либо собственный стыковочный продукт','Utair имеет свою технологию в Уфе; исторически N4/Икар обещали продолжения через KZN; RW присутствует в выдаче через SVX.',['UFA-E08','UFA-E11','UFA-E13'],'Улучшить полную поездку без новой локальной базы: единый билет, пригодное время, багаж и защита.','Новый прямой продукт P01, существующий самостоятельный билет и KEEP.','Проверить реальные продаваемые маршруты в обе стороны, комиссию/нетто-доход RW, договор ответственности, открытые места на всех плечах.',['E01','UFA-F05'],'CONDITIONAL: продуктовая альтернатива сформирована; текущие договоры RW UNKNOWN.','Действующий договор и выгодная полная поездка могут сделать большой локальный запуск ненужным для части OD; отсутствие договора не обнуляет отдельные билеты.',['UFA-P07-PARTNER'])
h('06','Летний международный луч на SSJ','Международный поток существует; есть опубликованный UFA–TBS Азимута и летняя сеть СНГ.',['UFA-E01','UFA-E02','UFA-E12','UFA-S55'],'Один самолёт может иметь более полезное международное применение в конкретном сезоне.','Те же два TOF вместо TBS, тот же борт и месяцы; новые Ту-214 = 0.','TBS substitution против P01 summer: права/допуски, единый OD, сборы, валютная корзина, собственные международные продажи.',['UFA-S55','расширение scope international из common_spec'],'CONDITIONAL: маршрутная замена задана; текущая ниша, права RW и экономика UNKNOWN.','Подтверждённый спрос/право/договор либо отсутствие их; не заменять факты общим ростом международного аэропортового потока.',['UFA-P08-TBS'])
h('07','Наземный подвоз как отдельная ниша','Есть 8-часовая карточка автобуса до остановки у SVX и местные автобусы в UFA.',['UFA-S21','UFA-S22','UFA-S23','UFA-S51'],'Для некоторых адресов, дальних редких рейсов или ценочувствительных групп полная корзина через соседний аэропорт может быть выгоднее.','Местный прямой рейс либо авиаподвоз; общий спрос одного адресного pool.','Сравнить адрес–терминал–назначение, цену багажа, доступность дня и ожидаемый ущерб; договорная защита не предполагается.',['UFA-F01','UFA-S21'],'CONDITIONAL: ниша сохранена; цены и надёжность конкретных дат UNKNOWN.','Датированная полная корзина и измеренная надёжность; автоматическая замена всей Уфы не поддерживается.',['UFA-P07-PARTNER','UFA-P00-KEEP'])
h('08','Автоматическое исключение Уфы по расстоянию до SVX','Местный аэропорт обслуживает миллионы пассажиров; опубликованы короткие платные UFA–SVX; наземный путь занимает часы.',['UFA-E01','UFA-S08','UFA-S21'],'Расстояние по прямой не измеряет полную поездку и не доказывает дублирование всей зоны охвата.','Маршрутное сравнение с адресным спросом и собственным перетоком.','Показать конкретный продукт, который проигрывает соседней базе по полной поездке; общего порога недостаточно.',['distance500km','UFA-F01'],'REJECTED_NARROW_CLAIM: универсальный отсев по 393 км не обоснован контрпримером действующего самостоятельного рынка.','Данные могут отклонить конкретный рейс или базу; географическое расстояние остаётся входом, а не достаточным экономическим критерием.',['UFA-P00-KEEP','UFA-P01-RADIAL'])
h('09','Промышленность и студенты как сегменты, не готовый контракт','Есть производственная цепочка ОДК, промышленная отгрузка города и 1858 иностранных студентов УУНиТ в отчёте 2024 года.',['UFA-S33','UFA-S34','UFA-S35'],'Могут создавать группы, сезонные визиты и командировки, но местонахождение и расписание поездок надо измерить.','Общий городской OD без придуманного контрактного блока.','Получить пары, периоды, поездки и travel budget; студенты не должны повторно входить в общий населённый pool.',['UFA-F04','UFA-F08'],'CONDITIONAL: сегментные механизмы оставлены; промышленный выпуск не конвертирован в пассажиров.','Проверенный travel block или календарь поездок; наличие центра ОДК не доказывает допуск/доступ RW к ТО ПД-8.',['UFA-P06-NORTH','UFA-P07-PARTNER'])
h('10','Северный банк как развитие C01','NUX/SGC имеют опубликованные продукты и собственный RW NUX; MRV и GOJ дают южный/западный выход.',['UFA-S09','UFA-S14','UFA-S15','UFA-S16'],'Пересадка может связать несмежные север–юг OD при правильных возвратах; обе стороны банка расходуют кресла.','Та же пара бортов в прямой системе и те же рейсы без синхронизации; исходные NJC/ARH/MCX/OMS не считаются закрытыми.','P09 против P05 direct2 и unbanked: один набор спроса, KEEP NUX, конкурентные пересадки, корпораты, 7/10/14 ночей и M90.',['C01','EC_H01','EC_H04','T16_HUB_UFA'],'CONDITIONAL: новый состав лучей и двухбортная геометрия; у исходного C01 остаётся Stage B по прежним парам.','Если банк не поддерживает возвраты/защиту либо проигрывает альтернативному применению, изменить состав; прежние пары не отвергать по непроверенному шаблону.',['UFA-P09-BANK-NS','UFA-P05-DIRECT2'])
js('hypotheses.json',{'schema':'UFA-local-hypotheses-v1','stage':'A','hypotheses':hyp,'lineage_policy':'Предшествующие результаты остаются frozen. Новые лучи — новая гипотеза или версия, не переписанный исторический вердикт. C02/C04/C30/C34 с UFA в пути переданы для общего сведения, не объявлены закрытыми локальным пакетом.','legacy_references':legacy})
# Stage B requests have bounded acceptance criteria and owners; missing inputs are not queued as approvals.
requests=[]
def req(i,owner,programmes_,fields,question,test,impact,sid):
 requests.append({'request_id':'UFA-B'+i,'owner':owner,'programme_ids':programmes_,'fields_needed':fields,'question':question,'distinguishing_test':test,'acceptance':test,'impact_without':'UNKNOWN: '+impact,'period':PERIOD,'unit':'Указана в fields_needed; результаты поездки/сегменты/RUB/месяц','coverage':'Stage B: общий расчёт или точный локальный договор; не запрос разрешения.','status':'OPEN_NOT_ECONOMIC_REJECTION','source_id':sid,'assumption_ids':'UFA-A12;UFA-A13;UFA-A14;UFA-A24'})
req('01','P05','P01/P02/P03/P07','demand_pool_id × месяц × сегмент; potential journeys; observed-air-to-potential mapping; own itinerary sales','Даёт ли прямой Уфы новые поездки, а не только перенос с RW через SVX?','Единые OD UFA/SVX/TOF/KEJ/OMS и outside; common choice и response; показать новые/перенесённые поездки, сегменты и один нетто-тариф.','нет прогноза загрузки и выручки','UFA-E13;PIN-P06')
req('02','P03 + RW sales','Все программы','Будущий KEEP flight/date/tail/crew; проданные локальные/сквозные поездки, обязательства, net fare','Как сохраняются собственные UFA–SVX/NUX и замещаемые назначения?','24 месяца; сверить WZ1026/WZ1081 и разовые WZ162 с фактическими обязательствами; привязать старые назначения, потери и высвобождение часов.','нет допустимой дельты или свободного самолёта','UFA-E17;PIN-P03')
req('03','P02','Все программы','physical_adjacent_leg_id, endpoints/via, даты UTC, continuity, sale/inventory, ticket protection, baggage, fare+as_of+lead','Какие опубликованные маршруты являются реальными конкурентными продуктами?','Reconcile TOF WZ1026+WZ5003, N4/EO через KZN, S7 через OVB; не превращать endpoint/корпоративные записи в кресла; проверить оба направления и точные аэропорты Москвы.','конкурентная доступность и цена не приняты','UFA-E13..16;PIN-P02')
req('04','P03 + аэропорт/RW','P01/P04/P06/P09','стоянки/слоты волны, overnight, crew rooms, линейное ТО RRJ-95, scope SJ-100/ПД-8, signed access, setup/exit lead','Доступен ли местный либо распределённый ресурс для запуска?','Получить операторское согласование; публичный ангар для ATR/B737 и провайдер не заменяют RW договор. Учесть GOJ/TOF/MRV/KEJ/NUX/SGC ночёвки.','операционная готовность UNKNOWN','UFA-E05..06;PIN-P03')
req('05','P03 + P05','P04/P09/P07','MCT RW, единый билет, багаж, межлинейные договоры, ответственность, обратные даты','Создаёт ли банк пригодный защищённый продукт?','M60/M90/M120 и 7/10/14 ночей; сравнить bank/unbanked; считать одну поездку и кресло на каждом плече. Utair45 не переносить.','хаб остаётся условным','UFA-E07..08;PIN-P06')
req('06','P03','P01..P09','N(t) plan/partial/delay/none; actual entry; common reserve; duty/rest; maintenance intervals; min turns; payload/range','Работают ли программы при реальных ресурсных ступенях?','Ротации всех месяцев, варианты SSJ100 и SJ-100 отдельно; учесть начальный/конечный перегон и восстановление. Проверить block+25%, turnaround90, unavailable reserve.','геометрия недели не операционная приёмка','resource_probe_results.json;PIN-P03')
req('07','P04','Все программы','Драйверы топлива, MTOW, пассажиров, turn, deice, стоянок, экипажа; будущие ставки; launch/base/exit cash dates','Какова граница экономического преимущества и потребность в финансировании?','Один rate owner/shared event; отдельные variable/full/cash. Полная стоимость 2027/28 не из старого sum profit. Построить безубыточность по нетто-тарифу/поездкам и funding frontier.','денежного победителя и даты прибыли нет','PIN-P04;UFA-E18')
req('08','P02 + P05','P01/P04/P06/P09','Помесячные конкуренты, same-basket fares/lead; ресурс для изменения времени/цены/частоты','Какой ответ конкурента реалистичен?','Utair север/feeder и действующая технология, Азимут MRV/история KEJ, S7 OVB, N4/EO KZN. Рост частоты лишь с доказанным ресурсом; известные/сценарные реакции различить.','ответ не равен нулю; величина неизвестна','PIN-P02;UFA-E08;UFA-E10..11')
req('09','P05 + RW/заказчики','P06/P09','Даты смен, пары, block seats, baggage, release/penalty; UFA–NUX/SGC own sales','Есть ли добавочная ценность новой даты на севере?','Новый конечный пассажир против переноса старой даты; использовать возвратные окна и конкретный оплачиваемый блок. Число работников вне РБ не квота.','корпоративная гипотеза условна','UFA-S41;UFA-S15..16')
req('10','P05 + P02 local','P01/P07/P08','Помесячные OD 2025/доступный2026, туризм/учёба/бизнес; catchment address, ground fare/time/reliability','Чем различаются зима, лето, межсезонье и периферия?','24 месяца; поездки жителей и гостей не суммировать с аэропортовыми сегментами; РБ не целиком catchment UFA. При отсутствии объёма оставить UNKNOWN.','сезонность и сегменты не калиброваны','UFA-E01..04;UFA-S35..43;UFA-S51')
req('11','P03/P04/P05 international','P08','Маршрутное право RW, пограничный процесс, тип/допуск, international charges, tariff basket, net currency','Может ли TBS заменить внутренний луч в те же летние месяцы?','P08 против P01 summer при том же борте; сохранить ноль новых Ту-214; проверить переток своих международных поездок.','международная ветвь не допущена к экономике','UFA-S55;UFA-E12')
req('12','P07/P08 coordinator + P06','Все программы','Complete P/KEEP bundles; input acceptance; information_set; target airport pairs; resource alternatives','Как Уфа входит в общую сеть 8–12 пар?','Пересчитать объединённый проект на общих demand pools/бортах/деньгах; UFA–OMS один общий рынок, не две независимые выручки. Сравнить все допустимые города и funding/stop conditions.','Stage A не финальное решение','PIN-P06;PIN-PLAN')
req('13','P05/P07 + владелец C01','P09 и исходный C01','OD NJC/SGC/ARH↔MRV/MCX/OMS; текущие собственные альтернативы; календарь возвратов','Меняет ли новый локальный состав лучей вывод исходного север–юг опыта?','Сохранить старый M90=0/6 как вердикт старого графика; новый график пересчитать с 7/10/14 ночами, не отбрасывать прежние пары из-за отсутствия их в четырёхлучевом шаблоне.','исходный C01 не завершён экономически','PIN-PLAN;H-UFA-10')
csvout('comparison_requests.csv',requests)
# Additional timing controls are explicit assumptions too.
for n,sub,val,unit,basis,ran,imp,ref in [
('26','Контроль без синхронизации','300','минут стыковки','Сравнить те же рейсы с 90-минутным банком и с пятичасовым ожиданием. Это размер опыта, не измеренное расписание.','90/300 минут; оба продукта требуют отдельной проверки допустимости и защиты.','Изолирует ценность синхронизации; стоянки и экипаж пересчитываются.','P03: новое время и операционная проверка; P05: ценность времени и пригодные поездки.'),
('27','Проектная пересадка в SVX','90','минут','Отдельный шаблон для контроля UFA–SVX–TOF. Уфимский MCT и 45 минут Utair не переносятся в SVX.','Подтверждённый MCT RW/SVX UNKNOWN; проверить 60/90/120 минут.','Шаблон 75+90+170=335 минут против 195 прямого блока. Это не прогноз цены или спроса.','P03/RW: MCT SVX, багаж, защита, реальная возможность сдвига feeder и восточного луча.')]:
 r={'assumption_id':'UFA-A'+n,'subject':sub,'value':val,'unit':unit,'period':PERIOD,'selected_by':'Исследователь Уфы, Sol 6.1 xhigh','basis':basis,'range_or_unknown':ran,'status':'SCENARIO_NOT_FORECAST','coverage':'Величина контролируемого опыта; не договор RW.','source_id':'LOCAL_DESIGN;PIN-P03;PIN-P06','affected_conclusions':imp,'sensitivity':'Полный повтор P03/P05/P06 при изменении времени.','how_to_refine':ref,'confidence_interval':False};A.append(r)
csvout('assumptions.csv',A)
for r in programmes:
 if r['programme_id']=='UFA-P04-BANK-EW':r['assumption_ids'].append('UFA-A26')
 if r['programme_id'] in ['UFA-P02-SVX','UFA-P07-PARTNER']:r['assumption_ids'].append('UFA-A27')
